}

.preview-font-sm {
    font-size: 0.8rem;
}

.preview-font-md {
    font-size: 1rem;
}

.preview-font-lg {
    font-size: 1.2rem;
}

.preview-compact {
    padding: 0.5rem !important;
    line-height: 1.2;
}

.preview-compact .preview-text {
    margin-bottom: 0.25rem;
}

.preview-meta {
    font-size: 0.75em;
    opacity: 0.7;
}

